            <p>${escapeHtml(story.summary)}</p>
            <a class="story-link" href="${escapeHtml(story.href)}">Read story</a>
          </article>
        </li>
      `;

      const EditorialSection = () => `
        <section class="section-block shell" aria-labelledby="editorial-heading">
          <div class="section-header">
