                  <li><a href="/contact">Contact</a></li>
                </ul>
              </nav>
            </div>
          </div>
        </footer>
      `;

      const App = () => `
        ${Header()}
        <main id="maincontent" class="page-main" tabindex="-1">
          ${Hero()}
          ${FeaturedProducts()}
          ${DealsSection()}
          ${EditorialSection()}
        </main>
        ${Footer()}
        <p id="status-message" class="sr-only" aria-live="polite"></p>
      `;

      document.getElementById("root").innerHTML = App();

      const statusMessage = document.getElementById("status-message");

      document.addEventListener("click", (event) => {
        const button = event.target.closest("[data-add-product]");
        if (!button) {
          return;
        }

        const productName = button.getAttribute("data-add-product");
        button.textContent = "Added";
        button.setAttribute("data-state", "added");
        statusMessage.textContent = `Added ${productName} to your bag.`;

        window.setTimeout(() => {
          if (!button.isConnected) {
            return;
          }

          button.textContent = "Add to bag";
          button.setAttribute("data-state", "idle");
        }, 1800);
